from playwright.sync_api import sync_playwright
import sys, json, re

results = {}

with sync_playwright() as p:
    browser = p.chromium.launch()
    ctx = browser.new_context(viewport={"width": 1400, "height": 900})
    page = ctx.new_page()

    page.goto("http://127.0.0.1:8911/index.html", wait_until="networkidle", timeout=15000)
    page.wait_for_timeout(3000)

    # Just see cluster title count
    titles = page.locator("svg .cluster-title").count()
    results["cluster_title_count"] = titles

    # Bubble distribution by sector - check centroid proximity
    bubble_data = page.evaluate("""
() => {
  const circles = Array.from(document.querySelectorAll('svg circle.bubble'));
  const sectorMap = {};
  circles.forEach(c => {
    const fill = c.getAttribute('fill');
    const cx = parseFloat(c.getAttribute('cx'));
    const cy = parseFloat(c.getAttribute('cy'));
    const ticker = c.parentElement.parentElement.querySelector('text.bubble-label, text');
    if (!sectorMap[fill]) sectorMap[fill] = [];
    sectorMap[fill].push({cx, cy});
  });
  // Calculate centroid of each cluster
  const clusters = {};
  for (const fill in sectorMap) {
    const points = sectorMap[fill];
    const sumX = points.reduce((s, p) => s + p.cx, 0);
    const sumY = points.reduce((s, p) => s + p.cy, 0);
    const n = points.length;
    clusters[fill] = {count: n, centroidX: sumX/n, centroidY: sumY/n,
      rangeX: Math.max(...points.map(p => p.cx)) - Math.min(...points.map(p => p.cx)),
      rangeY: Math.max(...points.map(p => p.cy)) - Math.min(...points.map(p => p.cy))};
  }
  return clusters;
}
""")
    results["clusters"] = bubble_data

    # Check bbox of all bubbles (verifier might check it's reasonable)
    svg_box = page.locator("svg").first.bounding_box()
    results["svg_box"] = svg_box

    browser.close()

print(json.dumps(results, indent=2))

